insert into public.site_settings (background_image_url, id, site_name, site_description, location_text, footer_description, seo_title, seo_description) values ('reference/split-gateway.webp', 1, 'Pura Pusering Jagat Pejeng', 'Dokumentasi budaya, sejarah, dan Virtual Tour 360 Pura Pusering Jagat Pejeng.', 'Desa Pejeng, Kecamatan Tampaksiring, Kabupaten Gianyar, Bali', 'Ruang untuk mengenal, mendokumentasikan, dan merawat warisan budaya Pura Pusering Jagat Pejeng.', 'Pura Pusering Jagat Pejeng — Warisan Budaya & Virtual Tour 360', 'Kenali sejarah, tata ruang Tri Mandala, dan dokumentasi budaya Pura Pusering Jagat Pejeng, Gianyar, Bali.') on conflict (id) do nothing;
insert into public.home_content (hero_image_url, hero_image_alt, intro_image_url, intro_image_alt, tour_cover_url, id, hero_title, hero_subtitle, hero_cta, history_cta, intro_title, intro_description, features_title, heritage_title, heritage_description, architecture_title, architecture_description, archaeology_title, archaeology_description, spiritual_title, spiritual_description, mandala_title, nista_description, madya_description, utama_description, tour_title, tour_description, tour_cta, gallery_title, conservation_title, conservation_description, is_published) values ('reference/main-gate.webp', 'Gerbang utama Pura Pusering Jagat Pejeng', 'reference/split-gateway.webp', 'Gerbang terbelah Pura Pusering Jagat Pejeng', 'reference/split-gateway.webp', 1, 'Menjelajahi Warisan Suci Pura Pusering Jagat Pejeng', 'Kenali sejarah, keunikan arsitektur, dan nilai budaya Pura Pusering Jagat Pejeng melalui pengalaman digital yang informatif dan interaktif.', 'Mulai Virtual Tour', 'Jelajahi Sejarah', 'Mengenal warisan di jantung Pejeng.', 'Pura Pusering Jagat berada di kawasan Pejeng, Tampaksiring, Gianyar. Ruang digital ini mengajak Anda mengenal narasi budaya dan tata ruang pura dengan tetap menghormati kesucian serta ketentuan dokumentasinya.', 'Warisan dalam setiap makna', 'Sejarah & warisan', 'Menelusuri kisah pura melalui sumber yang tersedia, dengan membedakan catatan sejarah dan penuturan tradisi.', 'Arsitektur tradisional', 'Mengenal susunan ruang dan unsur arsitektur pura yang dapat didokumentasikan atas izin pengelola.', 'Jejak arkeologis', 'Mempelajari peninggalan budaya secara bertanggung jawab, dengan informasi dan dokumentasi yang telah diverifikasi.', 'Nilai spiritual', 'Menghormati pura sebagai ruang suci dan memahami bahwa tidak semua bagian dapat dipublikasikan.', 'Tiga ruang, satu keharmonisan', 'Bagian luar dalam pembagian tata ruang Tri Mandala.', 'Bagian tengah yang menghubungkan ruang luar dengan ruang utama.', 'Bagian utama yang memiliki kedudukan paling suci dalam pembagian ruang pura.', 'Virtual Tour 360 Pura Pusering Jagat', 'Pengalaman 360° akan mengajak Anda mengenal area pura yang telah disetujui untuk dokumentasi digital.', 'Mulai Jelajah Virtual', 'Dokumentasi Pura Pusering Jagat', 'Pelestarian Warisan Budaya', 'Dokumentasi digital membantu memperkenalkan warisan budaya kepada generasi mendatang. Setiap narasi dan gambar disajikan dengan perhatian pada akurasi sumber, izin publikasi, dan kesucian pura.', true) on conflict (id) do nothing;
insert into public.about_content (image_url, image_alt, id, title, background, purpose, benefits, is_published) values ('reference/main-gate.webp', 'Gerbang utama Pura Pusering Jagat Pejeng', 1, 'Tentang Website Pura Pusering Jagat', 'Website ini dikembangkan sebagai ruang dokumentasi budaya Pura Pusering Jagat Pejeng. Penyajian informasi digital bertujuan membantu masyarakat mengenal pura melalui narasi, foto yang telah disetujui, dan pengalaman Virtual Tour 360 ketika tersedia.', 'Menyediakan akses informasi sejarah dan budaya yang mudah dipahami, mendukung dokumentasi objek yang diizinkan, serta memudahkan pengelola memperbarui informasi secara bertanggung jawab.', 'Arsip digital dapat mendukung pengenalan warisan budaya lintas generasi. Publikasi tetap mempertimbangkan ketentuan pengelola pura dan tidak menggantikan pengalaman maupun tata krama kunjungan langsung.', true) on conflict (id) do nothing;
insert into public.virtual_tour_settings (id, title, description, is_published) values (1, 'Virtual Tour Pura Pusering Jagat', 'Kenali ruang dan warisan Pura Pusering Jagat Pejeng melalui pengalaman Virtual Tour 360.', false) on conflict (id) do nothing;
insert into public.history_sections (image_url, image_alt, slug, title, content, status, source_note, source_url, sort_order) values ('reference/split-gateway.webp', 'Gerbang bagian luar Pura Pusering Jagat Pejeng', 'mengenal-pura', 'Mengenal Pura Pusering Jagat', 'Pura Pusering Jagat berada di kawasan Desa Pejeng, Kecamatan Tampaksiring, Kabupaten Gianyar, Bali. Artikel Desa Pejeng memperkenalkannya dalam konteks warisan budaya dan kehidupan spiritual masyarakat setempat.', 'published', 'Ringkasan lokasi umum dari kebutuhan pemilik dan artikel Desa Pejeng. Alamat rinci belum ditetapkan.', 'https://desa-pejeng-home.vercel.app/artikel/pura-pusering-jagat', 1) on conflict (slug) do nothing;
insert into public.history_sections (slug, title, content, status, source_note, source_url, sort_order) values ('makna-nama', 'Makna nama Pusering Jagat', 'Nama Pusering Jagat berkaitan dengan makna pusat dunia atau alam semesta. Makna ini disajikan sebagai bagian dari pemahaman budaya dan keyakinan masyarakat, bukan sebagai penetapan pusat geografis.', 'published', 'Parafrasa terbatas dari artikel Desa Pejeng; tanpa klaim pengukuran geografis.', 'https://desa-pejeng-home.vercel.app/artikel/pura-pusering-jagat', 2) on conflict (slug) do nothing;
insert into public.history_sections (slug, title, content, status, source_note, source_url, sort_order) values ('awal-dan-bali-kuno', 'Asal-usul dan kaitan dengan Bali Kuno', 'Pura dikaitkan dengan perkembangan peradaban Bali Kuno di kawasan Pejeng. Tahun pendirian pastinya belum diketahui. Artikel Desa Pejeng menyebut perkiraan abad ke-10 Masehi; perkiraan ini masih memerlukan pemeriksaan sumber primer dan konfirmasi pengelola sebelum dipublikasikan.', 'draft', 'Perbedaan tingkat kepastian: prompt menyatakan tahun pasti tidak diketahui; sumber web memuat perkiraan abad ke-10. Proposal dan wawancara belum tersedia.', 'https://desa-pejeng-home.vercel.app/artikel/pura-pusering-jagat', 3) on conflict (slug) do nothing;
insert into public.history_sections (slug, title, content, status, source_note, source_url, sort_order) values ('peninggalan-arkeologis', 'Peninggalan arkeologis', 'Kebutuhan penelitian yang disampaikan pemilik menyebut Bejana Sangku Sudamala berangka tahun 1251 Saka atau 1329 Masehi. Angka pada peninggalan ini tidak boleh dianggap sebagai tahun pasti pendirian pura. Nama, pembacaan angka, dan izin dokumentasinya perlu diperiksa pada proposal serta sumber primer.', 'draft', 'Hanya berasal dari prompt pemilik, bukan proposal yang telah dibaca. Jangan terbitkan sebelum verifikasi.', '', 4) on conflict (slug) do nothing;
insert into public.history_sections (image_url, image_alt, slug, title, content, status, source_note, source_url, sort_order) values ('reference/split-gateway.webp', 'Gerbang bagian luar Pura Pusering Jagat Pejeng', 'tri-mandala', 'Tata ruang Tri Mandala', 'Pembagian ruang Tri Mandala mencakup Nista Mandala, Madya Mandala, dan Utama Mandala. Secara umum, pembagian ini membedakan ruang luar, ruang tengah, dan ruang utama. Informasi rinci mengenai tiap objek di pura diterbitkan setelah observasi dan izin publikasi tersedia.', 'published', 'Struktur disebut pada prompt pemilik dan artikel Desa Pejeng. Tidak mengklaim denah hasil pengukuran.', 'https://desa-pejeng-home.vercel.app/artikel/pura-pusering-jagat', 5) on conflict (slug) do nothing;
insert into public.history_sections (slug, title, content, status, source_note, source_url, sort_order) values ('nilai-budaya-spiritual', 'Nilai budaya dan spiritual', 'Pengenalan budaya melalui media digital perlu menghormati pura sebagai ruang suci. Dokumentasi dan penyampaian informasi harus mengikuti arahan pengelola, terutama untuk pelinggih dan benda sakral yang tidak diizinkan untuk ditampilkan.', 'published', 'Prinsip etika dokumentasi dari batasan penelitian yang diberikan pemilik; bukan kutipan wawancara.', '', 6) on conflict (slug) do nothing;
insert into public.history_sections (slug, title, content, status, source_note, source_url, sort_order) values ('pelestarian-budaya', 'Pelestarian melalui dokumentasi', 'Dokumentasi digital memberi ruang untuk mempelajari warisan budaya tanpa melepaskan tanggung jawab terhadap sumber informasi. Narasi dapat diperbarui saat penelitian berkembang, sementara foto dan media hanya diterbitkan setelah mendapat persetujuan.', 'published', 'Tujuan sistem yang disampaikan pemilik. Tidak mengklaim hasil penelitian pengguna atau statistik pelestarian.', '', 7) on conflict (slug) do nothing;
